SET NOCOUNT ON; SET XACT_ABORT ON;
IF @@TRANCOUNT<>0 THROW 51001,'Run full installation outside a transaction.',1;
BEGIN TRY BEGIN TRANSACTION;
EXEC sys.sp_executesql N'-- Generated by tools/build.ps1. Execute the complete script in the selected user database.
-- One batch: nested DDL is compiled inside the transaction and caught on failure.
SET NOCOUNT ON;
SET XACT_ABORT ON;

IF DB_ID()<=4 THROW 51001,''Install into a user database.'',1;
IF CONVERT(int,SERVERPROPERTY(''ProductMajorVersion''))<14 OR
   (SELECT compatibility_level FROM sys.databases WHERE database_id=DB_ID())<140
    THROW 51001,''Core requires SQL Server 2017 and compatibility level 140 or newer.'',1;
DECLARE @Expected TABLE(Name sysname COLLATE Latin1_General_100_BIN2 PRIMARY KEY,Kind varchar(12),SourceHash varchar(64));
INSERT @Expected VALUES(N''Context_v1'',N''TYPE'',''E0BC22D82D3C07AB108A09EE42B23C6794A50A1228FCBF42235D3E82A1E793D7'');
